Here is the source code:
<source_code>
package f884;

import java.util.*;

public class Main {
    static int n;
    static char[] chars;
    static int[] vals;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        n = sc.nextInt();
        sc.nextLine();
        String s = sc.nextLine().trim();
        chars = s.toCharArray();

        vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = sc.nextInt();
        }
        sc.nextLine();

        // We need to find maximum beauty = sum of b_i where s_i = t_i
        // t is an antipalindromic permutation of s
        // For antipalindromic: for each i, t[i] != t[n-1-i]

        // The key insight: we want to maximize the number of positions where s[i] == t[i]
        // But we have the constraint that t[i] != t[n-1-i] for all i

        // For each pair (i, n-1-i), we have two positions that must have different characters
        // We can either keep s[i] at position i and s[n-1-i] at position n-1-i (if they are different)
        // Or swap them (if they are different)
        // Or assign different characters from the multiset

        // Since t must be a permutation of s, we need to count character frequencies

        // Let's think differently: we want to maximize sum of b_i where s_i = t_i
        // This is equivalent to maximizing the sum of b_i for positions where we keep s[i] in position i

        // For each pair (i, n-1-i), we have options:
        // 1. Keep both s[i] and s[n-1-i] in their original positions (if s[i] != s[n-1-i])
        // 2. Swap them (if s[i] != s[n-1-i])
        // 3. Assign different characters (but this might reduce beauty)

        // Actually, since we want to maximize beauty, we want to keep s[i] at position i as much as possible
        // But we need to ensure t[i] != t[n-1-i]

        // For each pair (i, n-1-i), if s[i] != s[n-1-i], we can keep both and get b[i] + b[n-1-i]
        // If s[i] == s[n-1-i], we cannot keep both (would violate antipalindromic condition)
        // So we need to change at least one of them

        // Let's calculate the base sum if we could keep all s[i] at position i
        // Then subtract the minimum "cost" to fix conflicts

        int totalBeauty = 0;
        for (int i = 0; i < n; i++) {
            totalBeauty += vals[i];
        }

        // For pairs where s[i] == s[n-1-i], we must change at least one position
        // We want to minimize the loss (i.e., keep the one with higher beauty)

        int loss = 0;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == chars[j]) {
                // We must change at least one of positions i or j
                // To minimize loss, we should change the one with smaller beauty
                loss += Math.min(vals[i], vals[j]);
            }
        }

        System.out.println(totalBeauty - loss);
    }
}
